import React from 'react'

export default function Leaderboard() {
    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-800">🏆 Leaderboard</h1>
            <p className="text-gray-500 mt-2">Top predictors this month</p>
            <div className="mt-6 bg-white rounded-xl shadow-md p-6 text-center text-gray-400">
                Coming soon: See who's leading the prediction game!
            </div>
        </div>
    )
}
